mapper.select:
select  from sys_permission


        and (permission_code like concat('%', #{keyword}, '%')
        or permission_name like concat('%', #{keyword}, '%')
        or api_path like concat('%', #{keyword}, '%'))

    and parent_id = #{parentId}
    and permission_code like concat('%', #{permissionCode}, '%')
    and permission_name like concat('%', #{permissionName}, '%')
    and permission_type = #{permissionType}
    and status = #{status}

order by sort_num asc, id asc

select distinct ur.user_id from sys_user_role ur
inner join sys_role_permission rp on rp.role_id = ur.role_id
where rp.permission_id = #{permissionId}
